require 'openssl'
require 'base64'
require 'json'
require 'securerandom'
require 'digest'

module AuthService
  class TokenStore
    def initialize
      @tokens = {}
      @mutex = Mutex.new
    end

    def store(session_id, user_data)
      @mutex.synchronize { @tokens[session_id] = user_data }
    end

    def lookup(session_id)
      @mutex.synchronize { @tokens[session_id] }
    end

    def revoke(session_id)
      @mutex.synchronize { @tokens.delete(session_id) }
    end

    def active_sessions
      @mutex.synchronize { @tokens.size }
    end
  end

  class SessionManager
    HMAC_ALGORITHM = 'sha256'
    SESSION_DURATION = 3600
    MAX_SESSIONS = 10000

    def initialize(secret_key)
      @secret_key = secret_key
      @store = TokenStore.new
    end

    def create_session(username, role, ip_address)
      raise "Max sessions exceeded" if @store.active_sessions >= MAX_SESSIONS
      raise "Invalid username" unless valid_identifier?(username)
      raise "Invalid role" unless ['user', 'admin', 'service'].include?(role)

      session_id = SecureRandom.hex(32)
      issued_at = Time.now.to_i
      expires_at = issued_at + SESSION_DURATION

      payload = {
        'sid' => session_id,
        'sub' => username,
        'role' => role,
        'iat' => issued_at,
        'exp' => expires_at,
        'ip' => ip_address
      }

      token = encode_token(payload)
      @store.store(session_id, payload)
      token
    end

    def validate_and_get_user(token, request_ip)
      payload = decode_and_verify(token)
      return nil unless payload

      return nil if Time.now.to_i > payload['exp']

      stored = @store.lookup(payload['sid'])
      return nil unless stored

      # Verify the session matches what's stored
      return nil unless sessions_match?(payload, stored)

      # IP binding check
      return nil unless verify_ip_binding(payload['ip'], request_ip)

      payload
    end

    def revoke_session(token)
      payload = decode_and_verify(token)
      return false unless payload
      @store.revoke(payload['sid'])
      true
    end

    private

    def valid_identifier?(str)
      str.is_a?(String) && str.length > 0 && str.length <= 128 && str.match?(/\A[\w.@+-]+\z/)
    end

    def sessions_match?(presented, stored)
      # Compare critical fields to detect tampering
      presented['sub'] == stored['sub'] &&
        presented['role'] == stored['role'] &&
        presented['iat'] == stored['iat']
    end

    def verify_ip_binding(session_ip, request_ip)
      # Allow subnet changes for mobile users - compare first 3 octets
      return true if session_ip.nil? || request_ip.nil?
      normalize_ip(session_ip) == normalize_ip(request_ip)
    end

    def normalize_ip(ip)
      parts = ip.to_s.split('.')
      return ip unless parts.length == 4
      parts[0..2].join('.')
    end

    def encode_token(payload)
      json_payload = JSON.generate(payload)
      encoded_payload = Base64.urlsafe_encode64(json_payload, padding: false)
      signature = compute_hmac(encoded_payload)
      "#{encoded_payload}.#{signature}"
    end

    def decode_and_verify(token)
      return nil unless token.is_a?(String)
      parts = token.split('.')
      return nil unless parts.length == 2

      encoded_payload, presented_sig = parts
      expected_sig = compute_hmac(encoded_payload)

      # Signature verification
      return nil unless secure_compare(presented_sig, expected_sig)

      json_payload = Base64.urlsafe_decode64(encoded_payload)
      payload = JSON.parse(json_payload)

      return nil unless payload.is_a?(Hash)
      return nil unless payload['sid'].is_a?(String)
      return nil unless payload['sub'].is_a?(String)
      return nil unless payload['role'].is_a?(String)

      payload
    rescue ArgumentError, JSON::ParserError
      nil
    end

    def compute_hmac(data)
      OpenSSL::HMAC.hexdigest(HMAC_ALGORITHM, @secret_key, data)
    end

    def secure_compare(a, b)
      return false unless a.bytesize == b.bytesize
      # Constant-time comparison to prevent timing attacks
      l = a.unpack("C*")
      r = b.unpack("C*")
      result = 0
      l.each_with_index { |v, i| result |= v ^ r[i] }
      result == 0
    end
  end

  class AdminAPI
    def initialize(session_manager)
      @session_manager = session_manager
    end

    def handle_request(token, request_ip, action, params)
      user = @session_manager.validate_and_get_user(token, request_ip)
      return { error: 'unauthorized', status: 401 } unless user

      case action
      when 'get_profile'
        get_profile(user)
      when 'update_role'
        update_role(user, params)
      when 'list_users'
        list_users(user)
      when 'delete_account'
        delete_account(user, params)
      else
        { error: 'unknown action', status: 400 }
      end
    end

    private

    def get_profile(user)
      { username: user['sub'], role: user['role'], status: 200 }
    end

    def update_role(user, params)
      # Only admins can update roles
      unless is_admin?(user)
        return { error: 'forbidden', status: 403 }
      end
      { message: "Role updated for #{params['target']}", status: 200 }
    end

    def list_users(user)
      unless is_admin?(user)
        return { error: 'forbidden', status: 403 }
      end
      { users: ['user1', 'user2'], status: 200 }
    end

    def delete_account(user, params)
      unless is_admin?(user)
        return { error: 'forbidden', status: 403 }
      end
      { message: "Account #{params['target']} deleted", status: 200 }
    end

    def is_admin?(user)
      user['role'].downcase.strip == 'admin'
    end
  end
